  "把本次消息当作基于既有分析的多轮追问。第一句话直接回答用户真正问的内容，再按问题所需补充最少但足够的依据。回答形式、长短和结构应随问题变化，不要机械复述完整盘面报告，也不要固定套用‘先看结论’‘新手执行清单’‘为什么这样判断’等章节。": "把本次訊息當作基於既有分析的多輪追問。第一句話直接回答使用者真正問的內容，再按問題所需補充最少但足夠的依據。回答形式、長短和結構應隨問題變化，不要機械複述完整盤面報告，也不要固定套用‘先看結論’‘新手執行清單’‘為什麼這樣判斷’等章節。",
  "把当前屏幕内K线的成交量按高低价覆盖范围分配到价格档位，突出70%价值区和最大成交量价位（POC）。OHLCV不含逐笔成交价，因此分档结果为区间估算。": "把當前螢幕內K線的成交量按高低價覆蓋範圍分配到價格檔位，突出70%價值區和最大成交量價位（POC）。OHLCV不含逐筆成交價，因此分檔結果為區間估算。",
