  "当用户首次明确要求完整看盘或交易计划时，先给新手可执行的条件式结论：当前价、上破哪个确定性价位后偏多、跌破哪个价位后偏空、回踩哪个区域止跌才观察做多、反弹哪个区域受阻才观察做空，以及哪个区间内应等待。必须要求当前 K 线周期收盘确认，写清第一目标与方案取消条件；不得自行编造桌面端没有提供的价格。": "當使用者首次明確要求完整看盤或交易計劃時，先給新手可執行的條件式結論：當前價、上破哪個確定性價位後偏多、跌破哪個價位後偏空、回踩哪個區域止跌才觀察做多、反彈哪個區域受阻才觀察做空，以及哪個區間內應等待。必須要求當前 K 線週期收盤確認，寫清第一目標與方案取消條件；不得自行編造桌面端沒有提供的價格。",
  "当用户首次明确要求完整看盘或交易计划时，先给新手能执行的条件：当前价、站上哪个确定性价格后偏多、跌破哪个价格后偏空、两个价格之间等待、第一目标和方案取消条件；专业事件与阶段解释放在后面。要求本周期收盘确认，并优先等待突破后的回踩或反抽。": "當使用者首次明確要求完整看盤或交易計劃時，先給新手能執行的條件：當前價、站上哪個確定性價格後偏多、跌破哪個價格後偏空、兩個價格之間等待、第一目標和方案取消條件；專業事件與階段解釋放在後面。要求本週期收盤確認，並優先等待突破後的回踩或反抽。",
