  "如果是任务请求，请遵守当前桌面端的本地权限和审批策略；不能安全执行时说明原因或请求澄清。": "如果是任務請求，請遵守當前桌面端的本地許可權和審批策略；不能安全執行時說明原因或請求澄清。",
  "如果用户是在请求查找、读取、列出、打开、修改本机文件/目录/配置/日志/skill/memory 路径，归类为 task_request 并按普通本地文件任务处理；可以返回必要的文件路径和操作结果，但不要主动解释这些路径与HaoLo底层实现的关系。": "如果使用者是在請求查詢、讀取、列出、開啟、修改本機檔案/目錄/配置/日誌/skill/memory 路徑，歸類為 task_request 並按普通本地檔案任務處理；可以返回必要的檔案路徑和操作結果，但不要主動解釋這些路徑與HaoLo底層實現的關係。",
