  "这里的 1R 代表这笔交易最初承担的风险。例如计划最多亏损 200 USDT，那么浮盈达到 200 USDT 就是达到 1R。保本位置会覆盖手续费和预估滑点，避免名义保本但实际仍然亏损。": "這裡的 1R 代表這筆交易最初承擔的風險。例如計劃最多虧損 200 USDT，那麼浮盈達到 200 USDT 就是達到 1R。保本位置會覆蓋手續費和預估滑點，避免名義保本但實際仍然虧損。",
  "这里计算的是包含手续费和预估滑点后的实际亏损，不是保证金比例。例如账户净值为 10,000 USDT，单笔风险设置为 2%，代表这笔交易最多亏损约 200 USDT。": "這裡計算的是包含手續費和預估滑點後的實際虧損，不是保證金比例。例如賬戶淨值為 10,000 USDT，單筆風險設定為 2%，代表這筆交易最多虧損約 200 USDT。",
  "这是从原任务自动续接的只读上下文。请把它当作此前已经确认的会话背景，不要向用户复述内部标记。": "這是從原任務自動續接的只讀上下文。請把它當作此前已經確認的會話背景，不要向使用者複述內部標記。",
  "这是规则理解演示，不代表收益回测或未来预测。若理解正确，请回复“确认”；若有任何偏差，直接指出哪一条不对，我会让智能体重新理解，再由本地规则引擎重新编译和预演。": "這是規則理解演示，不代表收益回測或未來預測。若理解正確，請回復“確認”；若有任何偏差，直接指出哪一條不對，我會讓智慧體重新理解，再由本地規則引擎重新編譯和預演。",
